// Levels.txt row count (excluding the blank "Expansion" separator row): the
// tripwire a future patch's changed level count should trip -- rerun
// tools/gen_level_flags.py and diff this value before trusting the table.
inline constexpr size_t LevelRowCount = 138;

// No level with this id exists in Levels.txt: {} for drlgType/inside is not a
// valid Levels.txt value, so it can't be mistaken for a real row.
inline constexpr LevelFlags UnknownLevel{ -1, -1, false, false, -1 };

inline constexpr const LevelFlags& FindLevelFlags(int32_t id) {
	for (const auto& entry : LevelFlagsTable) {
		if (entry.id == id) return entry;
	}
	return UnknownLevel;
}

// The monster classes (monstats.txt *hcIdx) a level names as its critters, Levels.txt
// cmon1-4: ambient animals that never attack, whatever their Align.
inline constexpr uint32_t CritterClasses[] = {
	149, // chicken
	151, // rat
	159, // bat
	268, // bug
	269, // scorpion
	283, // larva
	318, // snake
	319, // parrot
	339, // minispider
	556, // bunny
};

inline constexpr bool CritterMonster(uint32_t classId) {
	for (const auto critter : CritterClasses) {
		if (critter == classId) return true;
	}
	return false;
}

